import { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

import Container from '@mui/material/Container';
import Tabs from '@mui/material/Tabs';
import Tab from '@mui/material/Tab';
import Grid from '@mui/material/Grid';
import Box from '@mui/material/Box';
import Stack from '@mui/material/Stack';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import Divider from '@mui/material/Divider';
import Typography from '@mui/material/Typography';
import TextField from '@mui/material/TextField';
import InputAdornment from '@mui/material/InputAdornment';
import Chip from '@mui/material/Chip';
import Button from '@mui/material/Button';
import Pagination from '@mui/material/Pagination';
import Fab from '@mui/material/Fab';
import Drawer from '@mui/material/Drawer';
import IconButton from '@mui/material/IconButton';
import useMediaQuery from '@mui/material/useMediaQuery';
import { alpha, useTheme } from '@mui/material/styles';

import Iconify from 'src/components/iconify';
import LotteryCartPanel from 'src/components/lottery-cart-panel';
import { useTranslate } from 'src/locales';
import { useSettingsContext } from 'src/components/settings';
import { useSelector, useDispatch } from 'src/redux/store';
import { getWallet } from 'src/redux/slices/wallet';
import { formatDrawCartDate, getSecondsUntilDrawClose, isDrawClosed } from 'src/utils/draw-timezone';
import {
  fetchTchala,
  fetchTirages,
  fetchResultsByDate,
  type TirageItem,
  type ResultItem,
  type TchalaItem,
} from 'src/redux/slices/lottery';

type TabKey = 'lotos' | 'resultats' | 'regles' | 'tchala';
type CartItem = {
  id: string;
  boule: string;
  lotto: string;
  option: string;
  tirageId: string | number;
  tirageCloseTime?: string;
  playDisplay: string;
  tirageName: string;
  createdAt: number;
  amount: number;
  lineTotal: number;
};

const CART_STORAGE_KEY = 'lottery_detail_cart_items_v1';

const todayISO = () => new Date().toISOString().slice(0, 10);
const getCloseCountdownLabel = (t: (...args: any[]) => any, endTime?: string, now = new Date()) => {
  const totalSeconds = getSecondsUntilDrawClose(endTime, now);
  if (totalSeconds === null) return String(t('loto.countdown_unknown') || 'Closing in --m');
  if (totalSeconds <= 0) return String(t('loto.draw_closed') || 'Draw closed');
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  if (hours === 0) {
    return String(
      t('loto.countdown_minutes', { minutes, seconds }) || `Closing in ${minutes}m ${seconds}s`
    );
  }
  return String(
    t('loto.countdown_hours', { hours, minutes, seconds }) ||
      `Closing in ${hours}h ${minutes}m ${seconds}s`
  );
};
const isTirageClosed = (endTime?: string, now = new Date()) => isDrawClosed(endTime, now);
const fmtCartDate = (tirageCloseTime?: string, now = new Date()) => formatDrawCartDate(tirageCloseTime, now);
const getLottoLabel = (t: (...args: any[]) => any, lotto: string) => {
  if (lotto === 'L3') return t('loto.label_l3') || 'Loto3';
  if (lotto === 'L4') return t('loto.label_l4') || 'Loto4';
  if (lotto === 'L5') return t('loto.label_l5') || 'Loto5';
  if (lotto === 'MA') return t('loto.label_ma') || 'Mariage';
  if (lotto === 'BO') return t('loto.label_bo') || 'Borlette';
  if (lotto === 'P2') return t('loto.label_p2') || 'Pick2';
  if (lotto === 'P5') return t('loto.label_p5') || 'Pick5';
  if (lotto === 'L3B') return t('loto.label_l3b') || 'Loto3 Box';
  if (lotto === 'L4B') return t('loto.label_l4b') || 'Loto4 Box';
  return lotto;
};

export default function LotteryView() {
  const { t } = useTranslate();
  const theme = useTheme();
  const mdUp = useMediaQuery(theme.breakpoints.up('md'));
  const settings = useSettingsContext();
  const dispatch = useDispatch();

  const { wallet } = useSelector((s) => s.wallet);
  const { tirages, tchala, tchalaPageSize, tchalaPage, isLoading, results } = useSelector(
    (s) => s.lottery
  );

  const [openCart, setOpenCart] = useState(false);
  const [nowTs, setNowTs] = useState(() => Date.now());
  const [cartItems, setCartItems] = useState<CartItem[]>(() => {
    try {
      const raw = window.localStorage.getItem(CART_STORAGE_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? (parsed as CartItem[]) : [];
    } catch {
      return [];
    }
  });

  useEffect(() => {
    dispatch(getWallet());
    dispatch(fetchTirages());
    dispatch(fetchTchala({ page: 1 }));
  }, [dispatch]);

  useEffect(() => {
    const id = window.setInterval(() => setNowTs(Date.now()), 1000);
    return () => window.clearInterval(id);
  }, []);

  useEffect(() => {
    const syncCart = () => {
      try {
        const raw = window.localStorage.getItem(CART_STORAGE_KEY);
        if (!raw) {
          setCartItems([]);
          return;
        }
        const parsed = JSON.parse(raw);
        setCartItems(Array.isArray(parsed) ? (parsed as CartItem[]) : []);
      } catch {
        setCartItems([]);
      }
    };

    syncCart();
    window.addEventListener('focus', syncCart);
    window.addEventListener('storage', syncCart);
    return () => {
      window.removeEventListener('focus', syncCart);
      window.removeEventListener('storage', syncCart);
    };
  }, []);

  const location = useLocation();
  const navigate = useNavigate();
  const menuParam = (new URLSearchParams(location.search).get('menu') as TabKey) || 'resultats';

  const [currentTab, setCurrentTab] = useState<TabKey>(menuParam);
  const [q, setQ] = useState('');
  const [resultDate, setResultDate] = useState<string>(todayISO());

  useEffect(() => {
    if (menuParam !== currentTab) setCurrentTab(menuParam);
  }, [menuParam]); // eslint-disable-line

  useEffect(() => {
    const id = setTimeout(() => {
      if (currentTab === 'tchala') dispatch(fetchTchala({ page: 1, search: q }));
    }, 300);
    return () => clearTimeout(id);
  }, [q, currentTab, dispatch]);

  useEffect(() => {
    if (currentTab === 'resultats' && resultDate) {
      dispatch(fetchResultsByDate(resultDate));
    }
  }, [currentTab, resultDate, dispatch]);

  const handleChangeTab = useCallback(
    (_: React.SyntheticEvent, newValue: TabKey) => {
      setCurrentTab(newValue);
      navigate(`?menu=${newValue}`, { replace: true });
    },
    [navigate]
  );

  const handlePlay = useCallback(
    (tirage: TirageItem) => {
      navigate(`/lottery/${tirage.id}`);
    },
    [navigate]
  );

  const tabs = [
    {
      value: 'lotos',
      label: t('loto.lotos') || 'Lotos',
      icon: <Iconify icon="mdi:ticket-percent-outline" width={24} />,
    },
    {
      value: 'resultats',
      label: t('loto.results') || 'Résultats',
      icon: <Iconify icon="mdi:chart-bar" width={24} />,
    },
    {
      value: 'regles',
      label: t('loto.rules') || 'Règles',
      icon: <Iconify icon="mdi:help-circle-outline" width={24} />,
    },
    {
      value: 'tchala',
      label: t('loto.tchala') || 'Tchala',
      icon: <Iconify icon="mdi:book-open-variant" width={24} />,
    },
  ] as const;

  const totalPages = Math.max(1, Math.ceil(Number(tchala?.count || 0) / (tchalaPageSize || 1)));

  const tirageItems: TirageItem[] = tirages?.results ?? [];
  const resultItems: ResultItem[] = Array.isArray(results)
    ? results
    : (results as any)?.results ?? [];
  const tchalaItems: TchalaItem[] = tchala?.results ?? [];
  const cartTotal = cartItems.reduce((acc, item) => acc + (Number(item.lineTotal) || 0), 0);

  const persistCart = (nextItems: CartItem[]) => {
    setCartItems(nextItems);
    try {
      window.localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(nextItems));
    } catch {
      // ignore
    }
  };

  const handleRemoveCartItem = (id: string) => {
    persistCart(cartItems.filter((item) => item.id !== id));
  };

  const handleClearCart = () => {
    persistCart([]);
  };

  const CartContent = (
    <LotteryCartPanel
      title={t('cart.title') || 'PANIER'}
      itemCount={cartItems.length}
      closeLabel={t('common.close') || 'Fermer'}
      showCloseButton={!mdUp}
      onClose={() => setOpenCart(false)}
      clearLabel={t('cart.clear') || 'Clear cart'}
      showClearButton
      onClear={handleClearCart}
      clearDisabled={cartItems.length === 0}
      isEmpty={cartItems.length === 0}
      emptyTitle={t('cart.empty_title') || 'Ton panier est vide'}
      itemsContent={
        <Stack spacing={1.25} sx={{ p: 1.25 }}>
          {cartItems.map((item) => (
            <Card key={item.id} variant="outlined" sx={{ p: 0.8, borderRadius: 2 }}>
              <Stack direction="row" spacing={1} alignItems="flex-start">
                <Iconify icon="fluent:lottery-24-regular" width={30} />
                <Box sx={{ flex: 1, minWidth: 0 }}>
                  <Typography variant="body2" color="text.secondary">
                    {fmtCartDate(item.tirageCloseTime)}
                  </Typography>
                  <Typography variant="body2" sx={{ lineHeight: 1.12, fontWeight: 700 }}>
                    {item.tirageName || '-'}
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ lineHeight: 1.15, fontWeight: 700 }}>
                    {getLottoLabel(t, item.lotto || '')}
                  </Typography>
                  <Typography sx={{ fontSize: 18, fontWeight: 700 }}>
                    {item.playDisplay || item.boule}
                  </Typography>
                  <Typography
                    variant="body2"
                    color="text.secondary"
                    sx={{ fontWeight: 700, lineHeight: 1.15 }}
                  >
                    {`${t('betslip.mise') || 'Stake'}: ${item.amount} ${wallet?.currency || ''}`}
                  </Typography>
                </Box>
                <IconButton size="small" onClick={() => handleRemoveCartItem(item.id)}>
                  <Iconify icon="mdi:close-circle" width={24} />
                </IconButton>
              </Stack>
            </Card>
          ))}
        </Stack>
      }
      totalLabel={t('cart.total') || 'Total'}
      totalValue={`${cartTotal} ${wallet?.currency || ''}`}
      checkoutLabel={t('cart.checkout') || 'PLACER MON PARI'}
      cartItems={cartItems}
      onCartCleared={handleClearCart}
      onCheckoutSuccess={() => {
        if (!mdUp) setOpenCart(false);
      }}
      checkoutDisabled={cartItems.length === 0}
    />
  );

  const PALETTE = [
    ['#e53935', '#b71c1c'],
    ['#d81b60', '#880e4f'],
    ['#8e24aa', '#4a148c'],
    ['#5e35b1', '#311b92'],
    ['#3949ab', '#1a237e'],
    ['#1e88e5', '#0d47a1'],
    ['#00acc1', '#006064'],
    ['#43a047', '#1b5e20'],
    ['#fdd835', '#f57f17'],
    ['#fb8c00', '#e65100'],
  ];

  const pad2 = (v: any) =>
    String(v ?? '')
      .padStart(2, '0')
      .slice(-2);

  const seededGradient = (key: any) => {
    const s = String(key ?? '');
    const h = Array.from(s).reduce((acc, ch) => (acc * 31 + ch.charCodeAt(0)) % 4294967296, 0);
    const hue = h % 360;
    const hue2 = (hue + 330) % 360;
    return `linear-gradient(135deg, hsl(${hue},70%,45%), hsl(${hue2},70%,35%))`;
  };

  const bgFor = (v: any) => {
    const num = Number(pad2(v));
    if (Number.isFinite(num) && num >= 1 && num <= 10) {
      const [c1, c2] = PALETTE[num - 1];
      return `linear-gradient(135deg, ${c1}, ${c2})`;
    }
    return seededGradient(v);
  };

  const Ball = ({ v }: any) => (
    <span
      style={{
        display: 'inline-flex',
        width: 28,
        height: 28,
        borderRadius: '50%',
        alignItems: 'center',
        justifyContent: 'center',
        fontWeight: 700,
        fontSize: 12,
        color: '#fff',
        boxShadow: '0 1px 2px rgba(0,0,0,.3)',
        backgroundImage: bgFor(v),
      }}
    >
      {v}
    </span>
  );

  const chipSx = (v: any) => {
    const s = String(v ?? '')
      .padStart(2, '0')
      .slice(-2);
    const n = parseInt(s, 10);
    const h = Number.isNaN(n) ? 210 : (n * 37) % 360;
    return {
      color: '#fff',
      fontWeight: 700,
      boxShadow: '0 1px 2px rgba(0,0,0,.3)',
      backgroundImage: `linear-gradient(135deg, hsl(${h},70%,45%), hsl(${h},70%,35%))`,
      '& .MuiChip-label': { px: 0, width: 28, textAlign: 'center' },
    };
  };

  return (
    <Container maxWidth={settings.themeStretch ? false : 'lg'}>
      <Tabs
        value={currentTab}
        onChange={handleChangeTab}
        sx={{ mb: { xs: 2, md: 4 } }}
        allowScrollButtonsMobile
        variant="scrollable"
      >
        {tabs.map((tab) => (
          <Tab key={tab.value} value={tab.value} label={tab.label} icon={tab.icon} />
        ))}
      </Tabs>

      {currentTab === 'lotos' && (
        <Grid container spacing={2}>
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Stack spacing={1.5}>
                  {Number(tirages?.count || 0) === 0 && !isLoading && (
                    <Typography variant="body2" color="text.secondary">
                      {t('loto.no_draws') || 'Aucun tirage disponible.'}
                    </Typography>
                  )}

                  {tirageItems.map((tr: TirageItem) => (
                    <Card
                      key={tr.id}
                      variant="outlined"
                      sx={{
                        borderRadius: 2,
                        px: 2,
                        py: 1.75,
                        bgcolor: alpha(theme.palette.grey[500], 0.06),
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        flexWrap: 'wrap',
                        rowGap: 1,
                      }}
                    >
                      <Box sx={{ minWidth: 200 }}>
                        <Typography variant="subtitle1">{tr.name}</Typography>
                        <Stack
                          direction="row"
                          spacing={1}
                          sx={{ color: 'text.secondary', mt: 0.25 }}
                          alignItems="center"
                        >
                          <Iconify icon="fluent:lottery-24-regular" width={18} />
                          <Typography
                            variant="caption"
                            sx={{
                              color: isTirageClosed(tr.end_time, new Date(nowTs))
                                ? 'error.main'
                                : 'success.main',
                              fontWeight: 700,
                            }}
                          >
                            {getCloseCountdownLabel(t, tr.end_time, new Date(nowTs))}
                          </Typography>
                        </Stack>
                      </Box>
                      <Button
                        variant="contained"
                        color="success"
                        size="medium"
                        disabled={isTirageClosed(tr.end_time, new Date(nowTs))}
                        onClick={() => handlePlay(tr)}
                      >
                        {t('common.play') || 'Jouer'}
                      </Button>
                    </Card>
                  ))}
                </Stack>
              </CardContent>
            </Card>
          </Grid>

          {mdUp && (
            <Grid item xs={12} md={4}>
              <Card sx={{ position: 'sticky', top: 16 }}>{CartContent}</Card>
            </Grid>
          )}
        </Grid>
      )}

      {currentTab === 'resultats' && (
        <Card>
          <CardContent>
            <Stack spacing={2}>
              <Stack direction="row" alignItems="center" justifyContent="space-between">
                <Typography variant="h6">{t('results.title') || 'Résultats'}</Typography>
                <TextField
                  label={t('results.date_label') || 'Date du tirage'}
                  type="date"
                  size="small"
                  value={resultDate}
                  onChange={(e) => setResultDate(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                />
              </Stack>

              {resultItems.map((r: ResultItem) => (
                <Card key={r.id} variant="outlined" sx={{ borderRadius: 2 }}>
                  <Box sx={{ p: 2 }}>
                    <Typography variant="subtitle1">{r.tirage?.name}</Typography>
                    <Typography variant="caption" color="text.secondary">
                      {r.date}
                    </Typography>
                  </Box>
                  <Divider />
                  <Stack direction="row" spacing={1.25} sx={{ p: 2, flexWrap: 'wrap' }}>
                    {[r?.ball_1, r?.ball_2, r?.ball_3].filter(Boolean).map((b, i) => (
                      <Ball key={`${i}-${b}`} v={b} />
                    ))}
                  </Stack>
                </Card>
              ))}
            </Stack>
          </CardContent>
        </Card>
      )}

      {currentTab === 'regles' && (
        <Card>
          <CardContent>
            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.borlette.title') || 'Borlette'}
            </Typography>
            <Typography variant="subtitle1" sx={{ mb: 1 }}>
              {t('rules.borlette.general_title') || 'Règles Générales'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.borlette.general_text') || ''}
            </Typography>
            <ul>
              <li>
                <Typography variant="body2">{t('rules.borlette.payouts.first') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.borlette.payouts.second') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.borlette.payouts.third') || ''}</Typography>
              </li>
            </ul>
            <Typography variant="body2" paragraph>
              {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.loto3.title') || 'Loto 3'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto3.text') || ''}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto3.payout') || ''} {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.loto4.title') || 'Loto 4'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto4.text') || ''}
            </Typography>
            <ul>
              <li>
                <Typography variant="body2">{t('rules.loto4.options.one') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto4.options.two') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto4.options.three') || ''}</Typography>
              </li>
            </ul>
            <Typography variant="body2" paragraph>
              {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.loto5.title') || 'Loto 5'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.loto5.text') || ''}
            </Typography>
            <ul>
              <li>
                <Typography variant="body2">{t('rules.loto5.options.one') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto5.options.two') || ''}</Typography>
              </li>
              <li>
                <Typography variant="body2">{t('rules.loto5.options.three') || ''}</Typography>
              </li>
            </ul>
            <Typography variant="body2" paragraph>
              {t('rules.results_url_label') || 'Résultats :'}{' '}
              <a
                href="https://www.lotterypost.com/results/ny"
                target="_blank"
                rel="noopener noreferrer"
              >
                lotterypost.com/results/ny
              </a>
            </Typography>

            <Divider sx={{ my: 2 }} />

            <Typography variant="h6" sx={{ mb: 1 }}>
              {t('rules.mariage.title') || 'Le Mariage'}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.mariage.text') || ''}
            </Typography>
            <Typography variant="body2" paragraph>
              {t('rules.mariage.payout') || ''}
            </Typography>
          </CardContent>
        </Card>
      )}

      {currentTab === 'tchala' && (
        <Card>
          <CardContent>
            <Stack spacing={2}>
              <TextField
                value={q}
                onChange={(e) => setQ(e.target.value)}
                placeholder={t('loto.search_dream') || 'Quel est votre rêve ?'}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <Iconify icon="mdi:magnify" width={20} />
                    </InputAdornment>
                  ),
                }}
              />
              <Card variant="outlined" sx={{ borderRadius: 2 }}>
                <Box
                  sx={{
                    px: 2,
                    py: 1.25,
                    bgcolor: 'primary.dark',
                    color: 'primary.contrastText',
                    borderTopLeftRadius: 8,
                    borderTopRightRadius: 8,
                  }}
                >
                  <Stack direction="row" justifyContent="space-between">
                    <Typography fontWeight={700}>{t('tchala.dream') || 'Rêve'}</Typography>
                    <Typography fontWeight={700}>{t('tchala.number') || 'Numéro'}</Typography>
                  </Stack>
                </Box>
                <Stack sx={{ maxHeight: 520, overflow: 'auto', p: 1 }}>
                  {tchalaItems.map((row: TchalaItem) => (
                    <Stack
                      key={row.id}
                      direction="row"
                      alignItems="center"
                      justifyContent="space-between"
                      sx={{
                        px: 1.25,
                        py: 1,
                        borderBottom: (th) => `1px solid ${alpha(th.palette.grey[500], 0.16)}`,
                      }}
                    >
                      <Typography>{row.label}</Typography>
                      <Stack direction="row" spacing={1} flexWrap="wrap">
                        {row.numbers.map((n: string, i: number) => (
                          <Chip
                            key={i}
                            label={String(n).padStart(2, '0').slice(-2)}
                            size="small"
                            sx={chipSx(n)}
                          />
                        ))}
                      </Stack>
                    </Stack>
                  ))}
                </Stack>
              </Card>

              <Stack direction="row" justifyContent="center">
                <Pagination
                  page={tchalaPage}
                  count={totalPages}
                  onChange={(_, p) => dispatch(fetchTchala({ page: p, search: q }))}
                  color="primary"
                  size="small"
                />
              </Stack>
            </Stack>
          </CardContent>
        </Card>
      )}

      {!mdUp && currentTab === 'lotos' && (
        <>
          {!openCart && (
            <Fab
              aria-label={t('cart.title') || 'PANIER'}
              color="success"
              onClick={() => setOpenCart(true)}
              sx={{ position: 'fixed', right: 16, bottom: 100, zIndex: 1400 }}
            >
              <Iconify icon="mdi:cart-outline" width={22} />
              {cartItems.length > 0 && (
                <Box
                  sx={{
                    position: 'absolute',
                    top: -4,
                    right: -4,
                    minWidth: 20,
                    height: 20,
                    px: 0.5,
                    borderRadius: 999,
                    display: 'grid',
                    placeItems: 'center',
                    bgcolor: 'error.main',
                    color: 'common.white',
                    fontSize: 11,
                    fontWeight: 800,
                    lineHeight: 1,
                    border: (th) => `2px solid ${th.palette.background.paper}`,
                  }}
                >
                  {cartItems.length}
                </Box>
              )}
            </Fab>
          )}

          <Drawer
            anchor="right"
            open={openCart}
            onClose={() => setOpenCart(false)}
            PaperProps={{ sx: { width: '100%', maxWidth: 360 } }}
          >
            <Card
              elevation={0}
              sx={{ borderRadius: 0, height: '100%', display: 'flex', flexDirection: 'column' }}
            >
              {CartContent}
            </Card>
          </Drawer>
        </>
      )}

    </Container>
  );
}
