export type LottoCode =
  | 'BO'
  | 'P2'
  | 'P5'
  | 'L3'
  | 'L3B'
  | 'MA'
  | 'L4'
  | 'L4B'
  | 'L5'
  | null;

export type FormulaCode =
  | 'bp'
  | 'rv'
  | 'l3'
  | 'ma'
  | 'l4'
  | 'co'
  | 'p0'
  | 'p1'
  | 'p2'
  | 'p3'
  | 'p4'
  | 'p5'
  | 'p6'
  | 'p7'
  | 'p8'
  | 'p9'
  | 'l4c'
  | 'mac'
  | null;

export type ValidatedBoule = {
  valid: boolean;
  lotto: LottoCode;
  option: string;
  symb: string;
  formula: FormulaCode;
  boule_: string;
};

export type LotteryBetLike = {
  boule: string;
  lotto: Exclude<LottoCode, null> | string;
  option?: string | number;
};

const isAllDigits = (value: string) => /^\d+$/.test(value);

export const getValidedBoule = (bouleInput: string): ValidatedBoule => {
  const boule = (bouleInput || '').trim();
  let valid = true;
  let option = '1';
  let symb = '.';
  let lotto: LottoCode = null;
  let formula: FormulaCode = null;
  const lower = boule.toLowerCase();

  const formulaCodes = new Set([
    'bp',
    'rv',
    'l3',
    'ma',
    'l4',
    'co',
    'p0',
    'p1',
    'p2',
    'p3',
    'p4',
    'p5',
    'p6',
    'p7',
    'p8',
    'p9',
  ]);

  if (formulaCodes.has(lower)) {
    formula = lower as FormulaCode;
    return { valid, lotto, option, symb, formula, boule_: boule };
  }

  if (boule.length === 5 && boule[boule.length - 1] === '+') {
    formula = 'l4c';
    return { valid, lotto, option, symb, formula, boule_: boule };
  }
  if (boule.length === 5 && lower[boule.length - 1] === 'm') {
    formula = 'mac';
    return { valid, lotto, option, symb, formula, boule_: boule };
  }

  if (boule.length === 2 && isAllDigits(boule)) {
    lotto = 'BO';
  } else if (boule.length === 3 && lower[0] === 'p' && isAllDigits(boule.slice(1))) {
    lotto = 'P2';
  } else if (boule.length === 6 && lower[0] === 'p' && isAllDigits(boule.slice(1))) {
    lotto = 'P5';
  } else if (boule.length === 3 && isAllDigits(boule)) {
    lotto = 'L3';
  } else if (boule.length === 4 && lower[0] === 'b' && isAllDigits(boule.slice(1))) {
    lotto = 'L3B';
    if (new Set(boule.slice(1)).size < boule.slice(1).length) valid = false;
  } else if (boule.length === 4 && isAllDigits(boule)) {
    lotto = 'MA';
  } else if (boule.length === 6 && isAllDigits(boule.slice(0, 4))) {
    lotto = 'L4';
    option = boule.slice(-1);
    symb = boule.slice(-2, -1);
    if (!['0', '1', '2', '3', '5'].includes(option)) valid = false;
  } else if (boule.length === 5 && lower[0] === 'b' && isAllDigits(boule.slice(1))) {
    lotto = 'L4B';
    if (new Set(boule.slice(1)).size < boule.slice(1).length) valid = false;
  } else if (boule.length === 7 && isAllDigits(boule.slice(0, 5))) {
    lotto = 'L5';
    option = boule.slice(-1);
    if (!['0', '1', '2', '3'].includes(option)) valid = false;
  } else {
    lotto = null;
    valid = false;
  }

  return { valid, lotto, option, symb, formula, boule_: boule };
};

export const transformedBoule = (boule: string, lotto?: string | null) => {
  if (lotto === 'L4' || lotto === 'L5') return boule.slice(0, -2);
  if (lotto === 'P2' || lotto === 'P5' || lotto === 'L3B' || lotto === 'L4B') return boule.slice(1);
  return boule;
};

export const restoreTransformedBoule = (
  boule: string,
  lotto?: string | null,
  option = '',
  prefixe = ''
) => {
  if (lotto === 'L4' || lotto === 'L5') return `${boule}.${option}`;
  if (lotto === 'P2' || lotto === 'P5' || lotto === 'L3B' || lotto === 'L4B') return `${prefixe}${boule}`;
  return boule;
};

export const isValidNumber = (value: string) => /^\d+(\.\d+)?$/.test(value);

export const reverse_number = (num: string) => {
  const numStr = String(num);
  if (numStr.length <= 2) return numStr.split('').reverse().join('');
  if (numStr.length === 3) return numStr[0] + numStr.slice(1, 3).split('').reverse().join('');
  if (numStr.length === 4) return numStr.slice(2, 4) + numStr.slice(0, 2);
  return numStr[0] + numStr.slice(3, 5) + numStr.slice(1, 3);
};

export const isBoulePaire = (boule: string) => {
  const value = String(boule);
  if (value.length === 2) return value[0] === value[1];
  if (value.length === 3) return value[1] === value[2];
  if (value.length === 4) return value[0] === value[1] && value[1] === value[2] && value[2] === value[3];
  if (value.length === 5) return value[1] === value[2] && value[2] === value[3] && value[3] === value[4];
  return false;
};

export const generatePermutationsL4 = (input: string) => {
  const inputStr = String(input);
  const boule1 = inputStr.slice(0, 2);
  const boule2 = inputStr.slice(2);
  return [
    inputStr,
    boule2 + boule1,
    boule1.split('').reverse().join('') + boule2,
    boule2 + boule1.split('').reverse().join(''),
    boule1 + boule2.split('').reverse().join(''),
    boule2.split('').reverse().join('') + boule1,
    boule1.split('').reverse().join('') + boule2.split('').reverse().join(''),
    boule2.split('').reverse().join('') + boule1.split('').reverse().join(''),
  ];
};

export const generateBoulePaire = () => Array.from({ length: 10 }, (_, i) => `${i}${i}`);

export const generateBoulePoint = (point: string) => Array.from({ length: 10 }, (_, i) => `${i}${point}`);

export const generateBouleReverce = (bets: LotteryBetLike[]) => {
  const list: string[] = [];
  bets.forEach((bet) => {
    let prefix = '';
    if (bet.lotto === 'P2' || bet.lotto === 'P5') prefix = 'p';
    if (bet.lotto === 'L3B' || bet.lotto === 'L4B') prefix = 'b';
    const bouleReverce = restoreTransformedBoule(
      reverse_number(transformedBoule(bet.boule, bet.lotto)),
      bet.lotto,
      bet.lotto === 'L4' || bet.lotto === 'L5' ? String(bet.option || '') : '',
      prefix
    );
    if (!isBoulePaire(transformedBoule(bet.boule, bet.lotto)) && !list.includes(bouleReverce)) list.push(bouleReverce);
  });
  return list;
};

export const generateLotto3Auto = (bets: LotteryBetLike[]) => {
  const list: string[] = [];
  bets.forEach((bet) => {
    if (bet.lotto !== 'BO') return;
    for (let i = 0; i <= 9; i += 1) {
      const boule = `${i}${bet.boule}`;
      if (!list.includes(boule)) list.push(boule);
    }
  });
  return list;
};

export const generateMariageAuto = (bets: LotteryBetLike[]) => {
  const list: string[] = [];
  bets.forEach((a) => {
    bets.forEach((b) => {
      if (a.lotto !== 'BO' || b.lotto !== 'BO') return;
      const ab = `${a.boule}${b.boule}`;
      const ba = `${b.boule}${a.boule}`;
      if (!list.includes(ab) && !list.includes(ba)) list.push(ab);
    });
  });
  return list;
};

export const generateL4Auto = (bets: LotteryBetLike[], option: string) => {
  const list: string[] = [];
  bets.forEach((a) => {
    bets.forEach((b) => {
      if (a.lotto !== 'BO' || b.lotto !== 'BO') return;
      const value = `${a.boule}${b.boule}.${option}`;
      if (!list.includes(value)) list.push(value);
    });
  });
  return list;
};

export const generateCombo = (boule: string, option: string) => {
  const cleaned = boule.replace('.', '');
  if (cleaned.length !== 4 || !/^\d{4}$/.test(cleaned)) return [];
  const p = cleaned.split('');
  return [
    `${p[0]}${p[1]}${p[2]}${p[3]}_${option}`,
    `${p[2]}${p[3]}${p[0]}${p[1]}_${option}`,
    `${p[0]}${p[1]}${p[3]}${p[2]}_${option}`,
    `${p[3]}${p[2]}${p[0]}${p[1]}_${option}`,
    `${p[1]}${p[0]}${p[2]}${p[3]}_${option}`,
    `${p[2]}${p[3]}${p[1]}${p[0]}_${option}`,
    `${p[1]}${p[0]}${p[3]}${p[2]}_${option}`,
    `${p[3]}${p[2]}${p[1]}${p[0]}_${option}`,
  ];
};

export const generateMaCombo = (boule: string) => {
  const cleaned = boule.replace('.', '');
  if (cleaned.length !== 4 || !/^\d{4}$/.test(cleaned)) return [];
  const p = cleaned.split('');
  return [
    `${p[0]}${p[1]}${p[2]}${p[3]}`,
    `${p[0]}${p[1]}${p[3]}${p[2]}`,
    `${p[1]}${p[0]}${p[3]}${p[2]}`,
    `${p[1]}${p[0]}${p[2]}${p[3]}`,
  ];
};

export const generateAndHandleL4Complet = (boule: string, option: string) => {
  const cleaned = boule.replace('+', '');
  return [
    `${cleaned}_${option}`,
    `${cleaned[3]}${cleaned[2]}${cleaned[1]}${cleaned[0]}_${option}`,
    `${cleaned[1]}${cleaned[0]}${cleaned[2]}${cleaned[3]}_${option}`,
    `${cleaned[3]}${cleaned[2]}${cleaned[0]}${cleaned[1]}_${option}`,
    `${cleaned[0]}${cleaned[2]}${cleaned[1]}${cleaned[3]}_${option}`,
    `${cleaned[2]}${cleaned[3]}${cleaned[0]}${cleaned[1]}_${option}`,
    `${cleaned[1]}${cleaned[2]}${cleaned[0]}${cleaned[3]}_${option}`,
    `${cleaned[2]}${cleaned[3]}${cleaned[1]}${cleaned[0]}_${option}`,
  ];
};

export const generateAndHandleMaComplet = (boule: string) => {
  const cleaned = boule.replace('m', '');
  return [
    cleaned,
    `${cleaned[0]}${cleaned[1]}${cleaned[3]}${cleaned[2]}`,
    `${cleaned[1]}${cleaned[0]}${cleaned[2]}${cleaned[3]}`,
    `${cleaned[1]}${cleaned[0]}${cleaned[3]}${cleaned[2]}`,
  ];
};

export const formatBoule = (boule: string, lotto?: string | null, option = '') => {
  if (lotto === 'MA') return `${boule.slice(0, 2)}*${boule.slice(2)}`;
  if (lotto === 'L3B') return `${boule}B`;
  if (lotto === 'L4') return option === '5' ? boule : `${boule} (${option})`;
  if (lotto === 'L5') return `${boule} (${option})`;
  if (lotto === 'L4B') return `${boule}B`;
  if (lotto === 'P2' || lotto === 'P5') return `${boule}P`;
  return boule;
};
