import type { ReactNode } from 'react';
import { useState } from 'react';

import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import CardContent from '@mui/material/CardContent';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { alpha } from '@mui/material/styles';

import Iconify from 'src/components/iconify';
import { useAuthContext } from 'src/auth/hooks';
import { useSnackbar } from 'src/components/snackbar';
import { useTranslate } from 'src/locales';
import { getWallet } from 'src/redux/slices/wallet';
import { useDispatch } from 'src/redux/store';
import axios from 'src/utils/axios';
import { transformedBoule } from 'src/utils/lottery-games';

type CartTicketItem = {
  tirageId?: string | number;
  boule: string;
  lotto: string;
  option?: string;
  amount: number;
};

type LotteryCartPanelProps = {
  title: string;
  itemCount?: number;
  closeLabel: string;
  showCloseButton?: boolean;
  onClose?: () => void;
  clearLabel?: string;
  showClearButton?: boolean;
  onClear?: () => void;
  clearDisabled?: boolean;
  isEmpty: boolean;
  emptyTitle: string;
  itemsContent?: ReactNode;
  totalLabel: string;
  totalValue: ReactNode;
  checkoutLabel: string;
  cartItems: CartTicketItem[];
  onCartCleared: () => void;
  onCheckoutSuccess?: () => void;
  checkoutEndpoint?: string;
  cartStorageKey?: string;
  checkoutDisabled?: boolean;
};

export default function LotteryCartPanel({
  title,
  itemCount,
  closeLabel,
  showCloseButton = false,
  onClose,
  clearLabel = '',
  showClearButton = false,
  onClear,
  clearDisabled = false,
  isEmpty,
  emptyTitle,
  itemsContent,
  totalLabel,
  totalValue,
  checkoutLabel,
  cartItems,
  onCartCleared,
  onCheckoutSuccess,
  checkoutEndpoint = '/api/v1/lottery/create-ticket',
  cartStorageKey = 'lottery_detail_cart_items_v1',
  checkoutDisabled = false,
}: LotteryCartPanelProps) {
  const { t } = useTranslate();
  const { enqueueSnackbar } = useSnackbar();
  const { authenticated } = useAuthContext();
  const dispatch = useDispatch();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const buildPayload = (items: CartTicketItem[]) => {
    const grouped: Record<string, { tirage: string | number; bouleLists: any[] }> = {};
    items.forEach((item) => {
      const tirage = item.tirageId;
      if (tirage === '' || tirage === undefined || tirage === null) return;
      const key = String(tirage);
      if (!grouped[key]) grouped[key] = { tirage, bouleLists: [] };
      grouped[key].bouleLists.push({
        boule: String(transformedBoule(item.boule, item.lotto)),
        lotto: item.lotto,
        option: String(item.option ?? ''),
        montant: Number(item.amount) || 0,
      });
    });
    return { ticketData: Object.values(grouped) };
  };

  const handleCheckoutClick = async () => {
    if (isSubmitting || cartItems.length === 0) return;
    if (!authenticated) {
      enqueueSnackbar(t('login_required') || 'Login is required!', { variant: 'error' });
      return;
    }
    const payload = buildPayload(cartItems);
    if (payload.ticketData.length === 0) {
      enqueueSnackbar(t('lottery_detail.no_valid_draw_for_ticket') || 'No valid draw found.', {
        variant: 'error',
      });
      return;
    }
    try {
      setIsSubmitting(true);
      await axios.post(checkoutEndpoint, payload);
      onCartCleared();
      try {
        window.localStorage.setItem(cartStorageKey, JSON.stringify([]));
      } catch {
        // Ignore storage write failures.
      }
      dispatch(getWallet());
      enqueueSnackbar(t('lottery_detail.ticket_created') || 'Ticket created successfully!');
      onCheckoutSuccess?.();
    } catch (error: any) {
      const data = error?.response?.data;
      const errorMessage = t('lottery_detail.ticket_create_error') || 'Ticket creation failed';
      if (Array.isArray(data.data) && data.data.length > 0) {
        if (data.length === 0) {
          enqueueSnackbar(errorMessage, { variant: 'error' });
        } else {
          data?.data.forEach((msg: any) => {
            enqueueSnackbar(String(msg), { variant: 'error' });
          });
        }
      } else if (typeof data?.error === 'string') {
        enqueueSnackbar(data.error, { variant: 'error' });
      } else {
        enqueueSnackbar(errorMessage, { variant: 'error' });
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <>
      <Box sx={{ px: 2, py: 1.25, display: 'flex', alignItems: 'center', gap: 1 }}>
        <Iconify icon="mdi:cart-outline" width={20} />
        <Typography variant="subtitle1" fontWeight={700}>
          {title}
        </Typography>
        {typeof itemCount === 'number' && (
          <Box
            sx={{
              minWidth: 22,
              height: 22,
              px: 0.75,
              borderRadius: 999,
              display: 'grid',
              placeItems: 'center',
              bgcolor: 'success.main',
              color: 'common.white',
              fontSize: 12,
              fontWeight: 800,
              lineHeight: 1,
            }}
          >
            {itemCount}
          </Box>
        )}
        <Box sx={{ flexGrow: 1 }} />
        {showClearButton && (
          <IconButton aria-label={clearLabel} onClick={onClear} disabled={clearDisabled}>
            <Iconify icon="mdi:delete-sweep-outline" width={20} />
          </IconButton>
        )}
        {showCloseButton && (
          <IconButton aria-label={closeLabel} onClick={onClose}>
            <Iconify icon="mdi:close" width={20} />
          </IconButton>
        )}
      </Box>

      <Divider />

      {isEmpty ? (
        <CardContent sx={{ bgcolor: (th) => alpha(th.palette.grey[500], 0.06) }}>
          <Stack alignItems="center" spacing={1.5} sx={{ py: 3 }}>
            <Iconify icon="mdi:clipboard-edit-outline" width={64} />
            <Typography variant="subtitle1" fontWeight={700} textAlign="center">
              {emptyTitle}
            </Typography>
          </Stack>
        </CardContent>
      ) : (
        itemsContent
      )}

      <Divider />

      <Stack spacing={1} sx={{ p: 2 }}>
        <Stack direction="row" justifyContent="space-between">
          <Typography variant="subtitle2">{totalLabel}</Typography>
          <Typography variant="subtitle2">{totalValue}</Typography>
        </Stack>
        <Button
          variant="contained"
          color="success"
          size="large"
          fullWidth
          disabled={checkoutDisabled || isSubmitting}
          onClick={handleCheckoutClick}
        >
          {isSubmitting ? t('cart.processing') || 'Processing...' : checkoutLabel}
        </Button>
      </Stack>
    </>
  );
}
